function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var levels := new List<integer>;
  var maxLevel := 0;
  var currentLevel := 0;

  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = '(' then
    begin
      currentLevel += 1;
      if currentLevel > maxLevel then
        maxLevel := currentLevel;
      stack.Push(currentLevel);
    end
    else if parenString[i] = ')' then
    begin
      currentLevel -= 1;
      currentLevel := stack.Pop;
    end;
  end;

  for var i := 1 to maxLevel do
    levels.Add(0);

  for var i := 1 to stack.Count do
  begin
    levels[stack[i-1]] := i;
  end;

  Result := levels.ToArray;
end;

begin
end.




