function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var i := n - 1;
  var prefix := '';
  var suffix := '';
  while i > 0 do
  begin
    if str[i] = 'a' then
    begin
      prefix := str[1:i];
      break;
    end;
    i -= 1;
  end;

  if prefix = '' then
  begin
    Result := '';
    exit;
  end;

  var j := i - 1;
  while j >= 0 do
  begin
    if str[j] = 'a' then
    begin
      suffix := str[j + 1:i + 1];
      break;
    end;
    j -= 1;
  end;

  Result := prefix + ReverseString(suffix);
end;

begin
end.







