function ChangeBase(x : integer; base : integer): string;
begin
  if (base < 2) or (base > 10) then
  begin
    Result := 'Invalid base. Base must be between 2 and 10.';
    exit;
  end;

  var res := '';
  var n := x;

  while n > 0 do
  begin
    res := char(Ord('0') + (n mod 10)) + res;
    n := n div 10;
  end;

  if base > 10 then
  begin
    Result := res;
    exit;
  end;

  var digits := '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  for var i := 1 to base - 1 do
    res := res + char(Ord(digits[i]));

  Result := res;
end;

begin
end.








