function StrongestExtension(className: string; extensions: array of string): string;
begin
  var maxStrength := -1;
  var strongestExtension := '';

  foreach var extension in extensions do
  begin
    var CAP := 0;
    var SM := 0;

    for var i := 1 to extension.Length do
      if char.IsUpper(extension[i]) then
        CAP += 1
      else if char.IsLower(extension[i]) then
        SM += 1;

    var strength := CAP - SM;

    if strength > maxStrength then
    begin
      maxStrength := strength;
      strongestExtension := extension;
    end;
  end;

  Result := className + '.' + strongestExtension;
end;

begin
end.




