function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var absNum := Abs(num);

  while absNum > 0 do
  begin
    var digit := absNum mod 10;

    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;

    absNum := absNum div 10;
  end;

  Result := (evenCount, oddCount);
end;

begin
end.




function IntToMiniRoman(number: integer): string;
begin
  if (1 <= number) and (number <= 1000) then
  begin
    var roman := new string[13];
    roman[1] := 'i'; roman[2] := 'ii'; roman[3] := 'iii'; roman[4] := 'iv'; roman[5] := 'v'; roman[6] := 'vi'; roman[7] := 'vii'; roman[8] := 'viii'; roman[9] := 'ix'; roman[10] := 'x'; roman[11] := 'xl'; roman[12] := 'xc'; roman[13] := 'cd'; roman[14] := 'cm';

    var n := number;
    var res := '';

    for var i := 13 downto 1 do
    begin
      var div := n div i;
      var mod := n mod i;

      for var j := 1 to div do
        res := res + roman[i];

      if mod = 1 then
        res := res + roman[i];
    end;

    Result := res;
  end
  else
    Result := 'Invalid number';
end;

