function DoAlgebra(operator: array of string; operand: array of integer): integer;
begin
  var result := 0;
  var i := 0;
  while i < operand.Length - 1 do
  begin
    var op := operator[i];
    var val := operand[i];
    if op = '+' then
      result += val
    else if op = '-' then
      result -= val
    else if op = '*' then
      result *= val
    else if op = '//' then
      result := Floor(result / val)
    else if op = '**' then
      result := Power(result, val)
    else
      raise new Exception('Invalid operator');
    i += 1;
  end;
  Result := result;
end;

begin
end.




